      else begin
        baud<=216; shift<={1'b1,shift[9:1]}; bitn<=bitn+1'b1;
        if (bitn==9) begin
          active<=0; pos<=pos+1'b1;
          if (pos>=3 && pos<saved_digits+3) data<=data<<4;
          if (pos==saved_digits+4) busy<=0;
        end
      end
    end
